const icon=(name,cls='ui-icon')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[name]||ICONS.package}</svg>`;
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>{if(!el.querySelector('svg'))el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon,'nav-icon'))});document.querySelectorAll('[data-action-icon]').forEach(el=>{if(!el.querySelector('svg'))el.insertAdjacentHTML('afterbegin',icon(el.dataset.actionIcon,'button-icon'))})}

const $=id=>document.getElementById(id);const rub=n=>new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0}).format(Number(n)||0);const esc=s=>String(s??'').replace(/[&<>"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));
async function api(url,opt={}){const headers={'content-type':'application/json',...(authToken?{authorization:`Bearer ${authToken}`} : {}),...(opt.headers||{})};const r=await fetch(url,{...opt,headers});const d=await r.json().catch(()=>({}));if(r.status===401&&url!='/api/auth/login'){localStorage.removeItem('gtstore_token');authToken='';document.getElementById('authGate')?.classList.remove('hidden')}if(!r.ok)throw new Error(d.error||'Ошибка запроса');return d}
function toast(t){const el=$('toast');el.textContent=t;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function openModal(id){$(id).classList.add('open')}function closeModal(id){$(id).classList.remove('open')}
function bindNavigation(){document.querySelectorAll('.nav button').forEach(b=>b.onclick=()=>go(b.dataset.tab));document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeModal(b.dataset.close));}
function go(tab){document.querySelectorAll('.nav button,.section').forEach(x=>x.classList.remove('active'));document.querySelector(`.nav button[data-tab="${tab}"]`)?.classList.add('active');$(tab)?.classList.add('active');$('pageTitle').textContent=document.querySelector(`.nav button[data-tab="${tab}"]`)?.textContent.trim()||tab;}
async function init(){hydrateIcons();bindNavigation();shops=await api('/api/shops');members=can('team.manage')?await api('/api/members'):[];apiKeys=can('integrations.manage')?await api('/api/api-keys'):[];webhooks=can('integrations.manage')?await api('/api/webhooks'):[];const sel=$('shopSelect');sel.innerHTML=shops.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');shopId=sel.value||'demo';sel.onchange=()=>{shopId=sel.value;loadAll()};bindActions();await loadAll();await loadMarketing();animateAmbient()}
function bindActions(){
 $('newProduct').onclick=()=>openProduct();$('importProducts').onclick=()=>$('excelFile').click();$('excelFile').onchange=importProductsExcel;$('importCsvProducts').onclick=()=>$('csvFile').click();$('csvFile').onchange=importProductsCsv;$('exportProducts').onclick=exportProductsCsv;$('newCategory').onclick=()=>openCategory();$('saveProduct').onclick=saveProduct;$('saveCategory').onclick=saveCategory;$('productSearch').oninput=renderProducts;$('stockFilter').onchange=renderProducts;$('activeFilter').onchange=renderProducts;$('selectAll').onchange=e=>{selected=new Set(e.target.checked?products.map(p=>p.id):[]);renderProducts()};document.querySelectorAll('[data-bulk]').forEach(b=>b.onclick=()=>bulk(b.dataset.bulk));
 $('orderSearch').oninput=renderOrders;$('orderStatus').onchange=renderOrders;$('orderPayment').onchange=renderOrders;$('newManualOrder').onclick=openManualOrder;$('addManualItem').onclick=()=>addManualItem();$('saveManualOrder').onclick=saveManualOrder;$('customerSearch').oninput=renderCustomers;$('newPromo').onclick=()=>openModal('promoModal');$('savePromo').onclick=savePromo;$('newCampaign').onclick=()=>openModal('campaignModal');$('saveCampaign').onclick=saveCampaign;$('customerSegment').onchange=renderCustomers;$('exportCustomers').onclick=exportCustomersCsv;$('connectBot').onclick=openTelegramBotModal;$('newTelegramBot').onclick=openTelegramBotModal;$('saveNewTelegramBot').onclick=connectBot;$('disconnectBot').onclick=disconnectBot;$('saveTelegram').onclick=saveTelegram;$('sendTest').onclick=sendTest;$('addCommand').onclick=()=>addCommandRow();$('addMenuButton').onclick=()=>addMenuRow();$('syncCommands').onclick=syncTelegramCommands;$('runDiagnostics').onclick=runTelegramDiagnostics;$('setTelegramWebhook').onclick=()=>updateTelegramWebhook(false);$('autoTelegramWebhook').onclick=autoTelegramWebhook;$('deleteTelegramWebhook').onclick=()=>updateTelegramWebhook(true);$('saveShop').onclick=saveShop;$('newShop').onclick=()=>openModal('shopModal');$('saveNewShop').onclick=saveNewShop;$('newMember').onclick=()=>openModal('memberModal');$('saveMember').onclick=saveMember;$('newApiKey').onclick=()=>openModal('apiKeyModal');$('saveApiKey').onclick=saveApiKey;$('newWebhook').onclick=()=>openModal('webhookModal');$('saveWebhook').onclick=saveWebhook;$('exportData').onclick=exportData;$('period').onchange=loadAnalytics;
 $('pImageFile').onchange=e=>{pendingImage=e.target.files?.[0]||null;previewImage(pendingImage?URL.createObjectURL(pendingImage):$('pImage').value)};$('pImage').oninput=e=>{pendingImage=null;previewImage(e.target.value)};$('dropzone').ondragover=e=>{e.preventDefault();$('dropzone').classList.add('drag')};$('dropzone').ondragleave=()=> $('dropzone').classList.remove('drag');$('dropzone').ondrop=e=>{e.preventDefault();$('dropzone').classList.remove('drag');pendingImage=e.dataTransfer.files?.[0]||null;if(pendingImage)previewImage(URL.createObjectURL(pendingImage))};$('addVariant').onclick=()=>addVariantRow();
}
async function loadAll(){const s=shops.find(x=>x.id===shopId);$('sideShop').textContent=s?.name||'GtStore';$('openShop').href=`/shop/${s?.slug||'demo'}`;[categories,products,orders,customers]=await Promise.all([api(`/api/categories?shopId=${shopId}`),api(`/api/products?shopId=${shopId}`),api(`/api/orders?shopId=${shopId}`),api(`/api/customers?shopId=${shopId}`)]);renderCategories();renderProducts();renderOrders();renderCustomers();fillSettings();renderWorkspace();renderIntegrations();await loadTelegramStudio();await loadAnalytics()}
function renderCategories(){ $('categoryCount').textContent=categories.length;$('categoryList').innerHTML=`<button class="category-item active" data-cat="all"><span>Все товары</span><b>${products.length}</b></button>`+categories.map(c=>`<div class="category-row"><button class="category-item" data-cat="${c.id}"><span>${esc(c.name)}</span><b>${products.filter(p=>p.categoryId===c.id).length}</b></button><button class="icon-btn" onclick="editCategory('${c.id}')">⋯</button></div>`).join('');document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-cat]').forEach(x=>x.classList.remove('active'));b.classList.add('active');b.dataset.active='1';renderProducts(b.dataset.cat)});$('pCategory').innerHTML='<option value="">Без категории</option>'+categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}
function renderProducts(forceCat){const activeCat=forceCat||document.querySelector('[data-cat].active')?.dataset.cat||'all',q=$('productSearch').value.toLowerCase(),sf=$('stockFilter').value,af=$('activeFilter').value;let rows=products.filter(p=>(activeCat==='all'||p.categoryId===activeCat)&&(!q||[p.name,p.sku,(p.tags||[]).join(' ')].join(' ').toLowerCase().includes(q))&&(sf==='all'||(sf==='zero'?p.stock<=0:p.stock>0&&p.stock<=p.lowStock))&&(af==='all'||(af==='active'?p.active:!p.active)));$('productRows').innerHTML=rows.map(p=>{const cat=categories.find(c=>c.id===p.categoryId)?.name||'—',stock=p.stock<=0?'Нет':p.stock<=p.lowStock?`Мало: ${p.stock}`:p.stock;return `<tr><td><input type="checkbox" ${selected.has(p.id)?'checked':''} onchange="toggleProduct('${p.id}',this.checked)"></td><td><div class="product-cell"><img src="${esc(p.image)}"><div><b>${esc(p.name)}</b><small>${esc((p.tags||[]).join(' · '))}</small></div></div></td><td>${esc(cat)}</td><td>${esc(p.brand||'—')}</td><td><b>${esc(p.sku)}</b><small>${esc(p.barcode||'')}</small></td><td><b>${rub(p.price)}</b>${p.comparePrice?`<small class="old">${rub(p.comparePrice)}</small>`:''}</td><td><span class="stock ${p.stock<=0?'zero':p.stock<=p.lowStock?'low':''}">${stock}</span></td><td><span class="status ${p.active?'ok':'off'}">${p.active?'Опубликован':'Скрыт'}</span></td><td><button class="icon-btn" onclick="editProduct('${p.id}')">•••</button></td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Товары не найдены</td></tr>';$('selectedCount').textContent=selected.size;$('bulkBar').classList.toggle('hidden',!selected.size)}
window.toggleProduct=(id,on)=>{on?selected.add(id):selected.delete(id);renderProducts()};window.editProduct=id=>openProduct(products.find(p=>p.id===id));
function resetProduct(){editingProductId=null;pendingImage=null;['pName','pSku','pBarcode','pBrand','pSupplier','pCost','pPrice','pComparePrice','pStock','pWeight','pDescription','pTags','pSeoTitle','pSeoDescription','pImage'].forEach(id=>$(id).value='');$('pCategory').value='';$('pLowStock').value=5;$('pActive').checked=true;$('pImageFile').value='';$('variantRows').innerHTML='';previewImage('')}
function openProduct(p){resetProduct();if(p){editingProductId=p.id;$('productModalTitle').textContent='Редактировать товар';$('pName').value=p.name||'';$('pCategory').value=p.categoryId||'';$('pSku').value=p.sku||'';$('pBarcode').value=p.barcode||'';$('pBrand').value=p.brand||'';$('pSupplier').value=p.supplier||'';$('pCost').value=p.cost||'';$('pPrice').value=p.price;$('pComparePrice').value=p.comparePrice||'';$('pStock').value=p.stock;$('pLowStock').value=p.lowStock||5;$('pWeight').value=p.weight||'';$('pDescription').value=p.description||'';$('pTags').value=(p.tags||[]).join(', ');$('pSeoTitle').value=p.seoTitle||'';$('pSeoDescription').value=p.seoDescription||'';$('pImage').value=p.image||'';$('pActive').checked=p.active!==false;(p.variants||[]).forEach(v=>addVariantRow(v));previewImage(p.image)}else $('productModalTitle').textContent='Новый товар';openModal('productModal')}
function previewImage(src){$('pImagePreview').innerHTML=src?`<img src="${esc(src)}">`:'<b>Перетащи изображение</b><span>или нажми для выбора</span>'}
function addVariantRow(v={}){$('variantRows').insertAdjacentHTML('beforeend',`<div class="variant-row"><input placeholder="Название" value="${esc(v.name||'')}"><input type="number" placeholder="Цена" value="${v.price??''}"><input type="number" placeholder="Остаток" value="${v.stock??''}"><button onclick="this.parentElement.remove()">×</button></div>`)}
async function upload(file){const fd=new FormData();fd.append('shopId',shopId);fd.append('image',file);const r=await fetch('/api/uploads/product-image',{method:'POST',headers:authToken?{authorization:`Bearer ${authToken}`}:{},body:fd});const d=await r.json();if(!r.ok)throw new Error(d.error);return d.url}
async function saveProduct(){try{let image=$('pImage').value.trim();if(pendingImage)image=await upload(pendingImage);const variants=[...document.querySelectorAll('.variant-row')].map(r=>{const i=r.querySelectorAll('input');return{name:i[0].value.trim(),price:Number(i[1].value||0),stock:Number(i[2].value||0)}}).filter(v=>v.name);const payload={shopId,categoryId:$('pCategory').value,name:$('pName').value.trim(),sku:$('pSku').value.trim(),barcode:$('pBarcode').value.trim(),brand:$('pBrand').value.trim(),supplier:$('pSupplier').value.trim(),cost:Number($('pCost').value||0),price:Number($('pPrice').value),comparePrice:Number($('pComparePrice').value||0),stock:Number($('pStock').value||0),lowStock:Number($('pLowStock').value||5),weight:Number($('pWeight').value||0),seoTitle:$('pSeoTitle').value.trim(),seoDescription:$('pSeoDescription').value.trim(),description:$('pDescription').value.trim(),tags:$('pTags').value.split(',').map(x=>x.trim()).filter(Boolean),image,active:$('pActive').checked,variants};if(!payload.name||!Number.isFinite(payload.price))throw new Error('Укажите название и цену');await api(editingProductId?`/api/products/${editingProductId}`:'/api/products',{method:editingProductId?'PATCH':'POST',body:JSON.stringify(payload)});closeModal('productModal');toast('Товар сохранён');products=await api(`/api/products?shopId=${shopId}`);renderProducts();renderCategories()}catch(e){toast(e.message)}}
async function bulk(action){if(!selected.size)return;let value;if(['price','stock','price-percent'].includes(action)){value=prompt(action==='price'?'Новая цена':action==='stock'?'Новый остаток':'Изменение цены в %, например 10 или -5');if(value===null)return;if(!Number.isFinite(Number(value)))return toast('Введите число')}if(action==='delete'&&!confirm('Удалить выбранные товары?'))return;await api('/api/products/bulk',{method:'POST',body:JSON.stringify({shopId,ids:[...selected],action,value})});selected.clear();products=await api(`/api/products?shopId=${shopId}`);renderProducts();renderCategories();toast('Массовое действие выполнено')}
function openCategory(c){editingCategoryId=c?.id||null;$('categoryModalTitle').textContent=c?'Редактировать категорию':'Новая категория';$('cName').value=c?.name||'';$('cSort').value=c?.sort??99;$('cActive').checked=c?.active!==false;openModal('categoryModal')}
window.editCategory=id=>openCategory(categories.find(c=>c.id===id));async function saveCategory(){const payload={shopId,name:$('cName').value.trim(),sort:Number($('cSort').value||99),active:$('cActive').checked};if(!payload.name)return toast('Введите название');await api(editingCategoryId?`/api/categories/${editingCategoryId}`:'/api/categories',{method:editingCategoryId?'PATCH':'POST',body:JSON.stringify(payload)});closeModal('categoryModal');categories=await api(`/api/categories?shopId=${shopId}`);renderCategories();toast('Категория сохранена')}
function renderOrders(){const q=$('orderSearch').value.toLowerCase(),st=$('orderStatus').value,pay=$('orderPayment').value;const rows=orders.filter(o=>(st==='all'||o.status===st)&&(pay==='all'||(o.paymentStatus||'pending')===pay)&&(!q||[o.number,o.customer?.name,o.customer?.phone,o.customer?.telegramId].join(' ').toLowerCase().includes(q)));const paid=orders.filter(o=>(o.paymentStatus||'pending')==='paid'&&!['cancelled'].includes(o.status));$('orderMetrics').innerHTML=[['Всего заказов',orders.length],['Новые',orders.filter(o=>o.status==='new').length],['В работе',orders.filter(o=>['processing','ready'].includes(o.status)).length],['Оплачено',rub(paid.reduce((a,o)=>a+o.total,0))]].map(([a,b])=>`<div class="metric panel"><span>${a}</span><b>${b}</b></div>`).join('');$('orderRows').innerHTML=rows.map(o=>`<tr class="clickable-row" onclick="openOrderDetail('${o.id}')"><td><b>#${esc(o.number)}</b><small>${esc(o.delivery?.method||'')}</small></td><td>${esc(o.customer?.name)}<small>${esc(o.customer?.phone||o.customer?.telegramId||'')}</small></td><td>${o.items.slice(0,2).map(i=>`${esc(i.name)} × ${i.qty}`).join('<br>')}${o.items.length>2?`<small>+ ещё ${o.items.length-2}</small>`:''}</td><td><b>${rub(o.total)}</b></td><td><span class="status ${(o.paymentStatus||'pending')==='paid'?'ok':'off'}">${{pending:'Ожидает',paid:'Оплачен',refunded:'Возврат'}[o.paymentStatus||'pending']}</span></td><td>${esc(o.utm?.utm_source||o.source||'direct')}</td><td><select onclick="event.stopPropagation()" onchange="setOrderStatus('${o.id}',this.value)">${['new','processing','ready','done','cancelled'].map(s=>`<option value="${s}" ${o.status===s?'selected':''}>${{new:'Новый',processing:'В работе',ready:'Готов',done:'Выполнен',cancelled:'Отменён'}[s]}</option>`).join('')}</select></td><td>${new Date(o.createdAt).toLocaleString('ru-RU')}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Заказов пока нет</td></tr>'}
window.setOrderStatus=async(id,status)=>{await api(`/api/orders/${id}/status`,{method:'PATCH',body:JSON.stringify({status})});await refreshCrm();toast('Статус изменён')}
async function refreshCrm(){[orders,customers]=await Promise.all([api(`/api/orders?shopId=${shopId}`),api(`/api/customers?shopId=${shopId}`)]);renderOrders();renderCustomers();loadAnalytics()}
window.openOrderDetail=id=>{const o=orders.find(x=>x.id===id);if(!o)return;$('orderDetailContent').innerHTML=`<div class="modal-title"><div><small>ЗАКАЗ</small><h2>#${esc(o.number)}</h2></div><span class="status ${o.status==='done'?'ok':''}">${{new:'Новый',processing:'В работе',ready:'Готов',done:'Выполнен',cancelled:'Отменён'}[o.status]}</span></div><div class="order-detail-grid"><div><h3>Покупатель</h3><label>Имя<input id="odName" value="${esc(o.customer?.name)}"></label><label>Телефон<input id="odPhone" value="${esc(o.customer?.phone||'')}"></label><label>Telegram<input id="odTelegram" value="${esc(o.customer?.telegramId||'')}"></label><label>Комментарий<textarea id="odNotes" rows="4">${esc(o.notes||'')}</textarea></label></div><div><h3>Состав заказа</h3>${o.items.map(i=>`<div class="order-item"><span>${esc(i.name)} × ${i.qty}</span><b>${rub(i.price*i.qty)}</b></div>`).join('')}<div class="order-total"><span>Итого</span><b>${rub(o.total)}</b></div><label>Статус оплаты<select id="odPayment"><option value="pending">Ожидает оплаты</option><option value="paid">Оплачен</option><option value="refunded">Возврат</option></select></label><label>Доставка<input id="odDelivery" value="${esc(o.delivery?.method||'Самовывоз')}"></label></div></div><div class="modal-actions"><button class="btn" data-close="orderDetailModal" onclick="closeModal('orderDetailModal')">Закрыть</button><button class="btn primary" onclick="saveOrderDetail('${o.id}')">Сохранить</button></div>`;$('odPayment').value=o.paymentStatus||'pending';openModal('orderDetailModal')}
window.saveOrderDetail=async id=>{await api(`/api/orders/${id}`,{method:'PATCH',body:JSON.stringify({customer:{name:$('odName').value,phone:$('odPhone').value,telegramId:$('odTelegram').value},notes:$('odNotes').value,paymentStatus:$('odPayment').value,delivery:{method:$('odDelivery').value}})});closeModal('orderDetailModal');await refreshCrm();toast('Заказ сохранён')}
function openManualOrder(){$('moName').value='';$('moPhone').value='';$('moTelegram').value='';$('moNotes').value='';$('manualOrderItems').innerHTML='';addManualItem();openModal('manualOrderModal')}
function addManualItem(){const row=document.createElement('div');row.className='builder-row manual-item';row.innerHTML=`<select class="mi-product"><option value="">Выберите товар</option>${products.filter(p=>p.active&&p.stock>0).map(p=>`<option value="${p.id}">${esc(p.name)} — ${rub(p.price)} (остаток ${p.stock})</option>`).join('')}</select><input class="mi-qty" type="number" min="1" value="1"><button class="icon-btn">×</button>`;row.querySelector('button').onclick=()=>row.remove();$('manualOrderItems').appendChild(row)}
async function saveManualOrder(){const items=[...document.querySelectorAll('.manual-item')].map(r=>({productId:r.querySelector('.mi-product').value,qty:Number(r.querySelector('.mi-qty').value||1)})).filter(x=>x.productId);if(!items.length)return toast('Добавьте товар');await api('/api/orders/manual',{method:'POST',body:JSON.stringify({shopId,customer:{name:$('moName').value,phone:$('moPhone').value,telegramId:$('moTelegram').value},source:$('moSource').value,notes:$('moNotes').value,items})});closeModal('manualOrderModal');await loadAll();toast('Заказ создан')}
function renderCustomers(){const q=$('customerSearch').value.toLowerCase(),seg=$('customerSegment').value;const rows=customers.filter(c=>(!q||[c.name,c.phone,c.telegramId].join(' ').toLowerCase().includes(q))&&(seg==='all'||(seg==='new'?c.ordersCount===1:seg==='repeat'?c.ordersCount>1:seg==='vip'?c.revenue>=10000:true)));$('customerMetrics').innerHTML=[['Клиентов',customers.length],['Повторных',customers.filter(c=>c.ordersCount>1).length],['VIP',customers.filter(c=>c.revenue>=10000).length],['LTV',rub(customers.length?customers.reduce((a,c)=>a+c.revenue,0)/customers.length:0)]].map(([a,b])=>`<div class="metric panel"><span>${a}</span><b>${b}</b></div>`).join('');$('customerRows').innerHTML=rows.map(c=>`<tr><td><b>${esc(c.name)}</b><small>${c.ordersCount>1?'Постоянный клиент':'Новый клиент'}</small></td><td>${esc(c.phone||'—')}<small>${esc(c.telegramId||'')}</small></td><td><b>${c.ordersCount}</b></td><td><b>${rub(c.revenue)}</b></td><td>${rub(c.averageOrder)}</td><td>${new Date(c.lastOrderAt).toLocaleDateString('ru-RU')}</td><td><span class="status ${c.revenue>=10000?'ok':''}">${c.revenue>=10000?'VIP':c.ordersCount>1?'Повторный':'Новый'}</span></td></tr>`).join('')||'<tr><td colspan="7" class="empty">Клиентов пока нет</td></tr>'}
function exportCustomersCsv(){const rows=[['Имя','Телефон','Telegram','Заказов','Выручка','Средний чек','Последний заказ'],...customers.map(c=>[c.name,c.phone,c.telegramId,c.ordersCount,c.revenue,c.averageOrder,c.lastOrderAt])];const csv='\ufeff'+rows.map(r=>r.map(v=>`"${String(v??'').replace(/"/g,'""')}"`).join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=`customers-${shopId}.csv`;a.click();URL.revokeObjectURL(a.href)}
function renderAnalytics(){const cards=[['Открытия',analytics.visits,'↗'],['Просмотры',analytics.productViews,'◉'],['В корзину',analytics.cartAdds,'+'],['Заказы',analytics.orders,'▣'],['Выручка',rub(analytics.revenue),'₽'],['Конверсия',`${analytics.conversion}%`,'%']];const html=cards.map(x=>`<div class="metric panel"><span>${x[0]}</span><i>${x[2]}</i><b>${x[1]}</b><small>За выбранный период</small></div>`).join('');$('metrics').innerHTML=html;$('analyticsMetrics').innerHTML=html;$('funnel').innerHTML=[['Открытия',analytics.visits],['Просмотры',analytics.productViews],['Корзина',analytics.cartAdds],['Заказы',analytics.orders]].map(([n,v],i,a)=>`<div class="funnel-row"><span>${n}</span><b>${v}</b><div><i style="width:${Math.max(3,a[0][1]?v/a[0][1]*100:0)}%"></i></div></div>`).join('');$('events').innerHTML=(analytics.recentEvents||[]).slice(0,8).map(e=>`<div class="event"><i></i><div><b>${esc(e.type)}</b><small>${new Date(e.createdAt).toLocaleString('ru-RU')}</small></div></div>`).join('')||'<div class="empty">Событий пока нет</div>';$('logRows').innerHTML=(analytics.recentEvents||[]).map(e=>`<div class="log-row"><code>${esc(e.type)}</code><span>${esc(JSON.stringify(e.data||{}))}</span><time>${new Date(e.createdAt).toLocaleString('ru-RU')}</time></div>`).join('')||'<div class="empty">Лог пуст</div>';renderSources();renderTop();drawChart()}
function renderSources(){const max=Math.max(1,...(analytics.sources||[]).map(x=>x.value));$('sources').innerHTML=(analytics.sources||[]).map(x=>`<div class="source-row"><span>${esc(x.name)}</span><b>${x.value}</b><div><i style="width:${x.value/max*100}%"></i></div></div>`).join('')||'<div class="empty">Нет данных</div>'}
function renderTop(){$('topProducts').innerHTML=(analytics.topProducts||[]).map((x,i)=>`<div class="top-row"><b>${i+1}</b><span>${esc(x.name)}</span><strong>${x.value} шт.</strong></div>`).join('')||'<div class="empty">Продаж пока нет</div>'}
function drawChart(){const c=$('salesChart');if(!c)return;const dpr=devicePixelRatio||1,w=c.clientWidth||700,h=260;c.width=w*dpr;c.height=h*dpr;const g=c.getContext('2d');g.scale(dpr,dpr);g.clearRect(0,0,w,h);const s=analytics.series||[],max=Math.max(1,...s.map(x=>x.revenue));g.strokeStyle='rgba(211,125,82,.22)';for(let i=0;i<5;i++){const y=20+i*(h-40)/4;g.beginPath();g.moveTo(0,y);g.lineTo(w,y);g.stroke()}g.strokeStyle='#d37d52';g.lineWidth=3;g.beginPath();s.forEach((x,i)=>{const px=i/(Math.max(1,s.length-1))*w,py=h-24-x.revenue/max*(h-54);i?g.lineTo(px,py):g.moveTo(px,py)});g.stroke()}
function animateAmbient(){let tx=0,ty=0,raf;document.addEventListener('pointermove',e=>{tx=(e.clientX/innerWidth-.5)*16;ty=(e.clientY/innerHeight-.5)*16;if(!raf)raf=requestAnimationFrame(()=>{document.documentElement.style.setProperty('--mx',tx+'px');document.documentElement.style.setProperty('--my',ty+'px');raf=null})})}
bootstrap().catch(e=>{console.error(e);toast(e.message)});

function initials(name=''){return name.split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase()||'GT'}
function roleName(r){return{owner:'Владелец',admin:'Администратор',manager:'Менеджер',catalog:'Контент-менеджер',analyst:'Аналитик'}[r]||r}
function renderWorkspace(){if(!$('memberRows'))return;$('memberRows').innerHTML=members.map(m=>`<div class="member-row"><span class="member-avatar">${initials(m.name)}</span><div><b>${esc(m.name)}</b><small>${esc(m.email)}</small></div><span class="role">${roleName(m.role)}</span>${m.role==='owner'?'<span></span>':`<button class="icon-btn" onclick="removeMember('${m.id}')">×</button>`}</div>`).join('');$('shopUsage').textContent=`${shops.length} / 5`;$('memberUsage').textContent=`${members.length} / 10`;$('shopUsageBar').style.width=Math.min(100,shops.length/5*100)+'%';$('memberUsageBar').style.width=Math.min(100,members.length/10*100)+'%'}
async function saveMember(){try{const m=await api('/api/members',{method:'POST',body:JSON.stringify({name:$('mName').value.trim(),email:$('mEmail').value.trim(),role:$('mRole').value})});members.push(m);closeModal('memberModal');$('mName').value='';$('mEmail').value='';renderWorkspace();toast('Участник приглашён')}catch(e){toast(e.message)}}
window.removeMember=async id=>{if(!confirm('Удалить участника?'))return;try{await api(`/api/members/${id}`,{method:'DELETE'});members=members.filter(x=>x.id!==id);renderWorkspace();toast('Участник удалён')}catch(e){toast(e.message)}}
async function saveNewShop(){try{const s=await api('/api/shops',{method:'POST',body:JSON.stringify({name:$('newShopName').value.trim(),slug:$('newShopSlug').value.trim(),description:$('newShopDescription').value.trim()})});shops.push(s);shopId=s.id;closeModal('shopModal');$('newShopName').value='';$('newShopSlug').value='';$('newShopDescription').value='';await initShopSelect();await loadAll();renderWorkspace();toast('Магазин создан')}catch(e){toast(e.message)}}
async function initShopSelect(){const sel=$('shopSelect');sel.innerHTML=shops.map(x=>`<option value="${x.id}" ${x.id===shopId?'selected':''}>${esc(x.name)}</option>`).join('')}
function renderIntegrations(){if(!$('apiKeyRows'))return;$('apiKeyRows').innerHTML=apiKeys.map(k=>`<div class="integration-row"><div><b>${esc(k.name)}</b><small><code>${esc(k.key)}</code> · ${new Date(k.createdAt).toLocaleDateString('ru-RU')}</small></div><span class="status ok">Активен</span><button class="icon-btn" onclick="removeApiKey('${k.id}')">×</button></div>`).join('')||'<div class="empty">Ключей пока нет</div>';$('webhookRows').innerHTML=webhooks.map(w=>`<div class="integration-row"><div><b>${esc(w.event)}</b><small>${esc(w.url)}</small></div><span class="status ${w.active?'ok':''}">${w.active?'Активен':'Выключен'}</span><button class="icon-btn" onclick="removeWebhook('${w.id}')">×</button></div>`).join('')||'<div class="empty">Webhook-ов пока нет</div>'}
async function saveApiKey(){try{const k=await api('/api/api-keys',{method:'POST',body:JSON.stringify({name:$('apiKeyName').value.trim()})});apiKeys.push({...k,key:k.key.slice(0,8)+'••••••••'});closeModal('apiKeyModal');$('apiKeyName').value='';renderIntegrations();navigator.clipboard?.writeText(k.key);toast('Ключ создан и скопирован')}catch(e){toast(e.message)}}
window.removeApiKey=async id=>{await api(`/api/api-keys/${id}`,{method:'DELETE'});apiKeys=apiKeys.filter(x=>x.id!==id);renderIntegrations();toast('Ключ удалён')}
async function saveWebhook(){try{const w=await api('/api/webhooks',{method:'POST',body:JSON.stringify({url:$('webhookUrl').value.trim(),event:$('webhookEvent').value})});webhooks.push(w);closeModal('webhookModal');$('webhookUrl').value='';renderIntegrations();toast('Webhook добавлен')}catch(e){toast(e.message)}}
window.removeWebhook=async id=>{await api(`/api/webhooks/${id}`,{method:'DELETE'});webhooks=webhooks.filter(x=>x.id!==id);renderIntegrations();toast('Webhook удалён')}
async function exportData(){try{const data=await api(`/api/export?shopId=${shopId}`),blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`gtstore-${data.shop?.slug||shopId}-export.json`;a.click();URL.revokeObjectURL(a.href);toast('Экспорт подготовлен')}catch(e){toast(e.message)}}


/* v2.3 ACCESS: token sessions, roles and protected interface */
let billing={};
async function bootstrap(){
  bindLogin();
  if(authToken){
    try{const s=await api('/api/session');currentUser=s.user;permissions=s.permissions||[];await enterWorkspace();return}catch(e){console.warn(e)}
  }
  $('authGate')?.classList.remove('hidden');
}
function bindLogin(){
  $('loginButton')?.addEventListener('click',async()=>{try{const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:$('loginEmail').value.trim(),password:$('loginPassword').value})});authToken=d.token;currentUser=d.user;permissions=d.permissions||[];localStorage.setItem('gtstore_token',authToken);await enterWorkspace();toast('Защищённая сессия открыта')}catch(e){toast(e.message)}});
  $('loginPassword')?.addEventListener('keydown',e=>{if(e.key==='Enter')$('loginButton').click()});
  $('logoutButton')?.addEventListener('click',logout);
}
async function enterWorkspace(){
  $('authGate')?.classList.add('hidden');
  renderAccess();
  await init();
  if(can('team.manage')){try{billing=await api('/api/billing');renderBilling()}catch(e){console.warn(e)}}
  document.querySelectorAll('.plan-select').forEach(btn=>btn.addEventListener('click',()=>selectPlan(btn.dataset.plan)));
  document.querySelectorAll('[data-period]').forEach(btn=>btn.addEventListener('click',()=>setBillingPeriod(btn.dataset.period)));
  $('cancelPlan')?.addEventListener('click',()=>updateBilling({status:'cancelled'}));
  $('changePayment')?.addEventListener('click',async()=>{const card=prompt('Последние 4 цифры новой карты','4242');if(card&&/^\d{4}$/.test(card))await updateBilling({paymentMethod:'•••• '+card})});
}
async function logout(){try{await api('/api/auth/logout',{method:'POST'})}catch{}localStorage.removeItem('gtstore_token');authToken='';currentUser=null;permissions=[];location.reload()}
function renderAccess(){
  if(!currentUser)return;
  $('accessName').textContent=currentUser.name;
  $('accessRole').textContent=roleName(currentUser.role);
  $('accessAvatar').textContent=initials(currentUser.name);
  const rules={marketing:'orders.manage',team:'team.manage',integrations:'integrations.manage',billing:'team.manage',analytics:'analytics.view',orders:'orders.view',customers:'orders.view',telegram:'telegram.manage',settings:'settings.manage'};
  for(const [tab,perm] of Object.entries(rules)){const btn=document.querySelector(`.nav button[data-tab="${tab}"]`);if(btn)btn.hidden=!can(perm)}
  ['newShop'].forEach(id=>{if($(id))$(id).hidden=!can('shops.manage')});
  ['newProduct','newCategory'].forEach(id=>{if($(id))$(id).hidden=!can('catalog.manage')});
  document.body.dataset.role=currentUser.role;
}
async function updateBilling(patch){billing=await api('/api/billing',{method:'PATCH',body:JSON.stringify(patch)});renderBilling();toast('Данные подписки обновлены')}
const PLAN_CATALOG={base:{name:'Base',price:1999},pro:{name:'Pro',price:2999},ultima:{name:'Ultima',price:4999}};
let billingPeriod='month';
function setBillingPeriod(period){billingPeriod=period==='year'?'year':'month';document.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('active',b.dataset.period===billingPeriod));document.querySelectorAll('[data-month-price]').forEach(el=>{const monthly=Number(el.dataset.monthPrice);el.textContent=billingPeriod==='year'?rub(Math.round(monthly*.85)):rub(monthly);const suffix=el.parentElement.querySelector('span');if(suffix)suffix.textContent=billingPeriod==='year'?'/ месяц при оплате за год':'/ месяц'});}
async function selectPlan(plan){const cfg=PLAN_CATALOG[plan];if(!cfg)return;const annual=billingPeriod==='year';const amount=annual?Math.round(cfg.price*12*.85):cfg.price;const confirmed=confirm(`Подключить тариф ${cfg.name} за ${rub(amount)} ${annual?'в год':'в месяц'}?`);if(!confirmed)return;await updateBilling({plan,status:'active',billingPeriod,monthlyPrice:cfg.price,chargedAmount:amount,nextPaymentAt:new Date(Date.now()+(annual?365:30)*864e5).toISOString()});toast(`Тариф ${cfg.name} подключён`)}
function renderBilling(){if(!$('billingState'))return;const active=billing.status==='active',trial=billing.status==='trial';const plan=PLAN_CATALOG[billing.plan]||PLAN_CATALOG.pro;$('billingState').textContent=active?'Подписка активна':trial?'Пробный период':'Подписка отменена';$('billingState').className='status '+((active||trial)?'ok':'');$('planStatus').textContent=active?'Активна':trial?'Trial':'Отменена';$('currentPlanName').textContent=plan.name;$('planDate').textContent=trial?`Пробный период до ${new Date(billing.trialEndsAt).toLocaleDateString('ru-RU')}`:billing.nextPaymentAt?`Следующее списание ${new Date(billing.nextPaymentAt).toLocaleDateString('ru-RU')}`:'Автопродление отключено';$('paymentMethod').textContent=billing.paymentMethod||'Не добавлен';document.querySelectorAll('[data-plan-card]').forEach(card=>card.classList.toggle('current',card.dataset.planCard===billing.plan));document.querySelectorAll('.plan-select').forEach(btn=>{const current=btn.dataset.plan===billing.plan&&active;btn.disabled=current;btn.textContent=current?'Текущий тариф':`Выбрать ${PLAN_CATALOG[btn.dataset.plan].name}`});setBillingPeriod(billing.billingPeriod||'month');$('invoiceRows').innerHTML=(billing.invoices||[]).map(i=>`<div class="invoice-row"><div><b>${esc(i.description||'GtStore')}</b><small>${new Date(i.date).toLocaleDateString('ru-RU')}</small></div><strong>${rub(i.amount)}</strong><span class="status ${i.status==='paid'||i.status==='trial'?'ok':''}">${i.status==='trial'?'Trial':i.status}</span></div>`).join('')||'<div class="empty">Операций пока нет</div>'}

function csvEscape(v){const s=String(v??'');return /[";,\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}
function exportProductsCsv(){const heads=['name','sku','barcode','brand','supplier','cost','price','comparePrice','stock','lowStock','active','tags','description','image'];const lines=[heads.join(';'),...products.map(p=>heads.map(k=>csvEscape(k==='tags'?(p.tags||[]).join('|'):p[k])).join(';'))];const blob=new Blob(['\ufeff'+lines.join('\n')],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`gtstore-products-${shopId}.csv`;a.click();URL.revokeObjectURL(a.href);toast('CSV экспортирован')}
function parseCsv(text){const rows=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(q&&c==='"'&&n==='"'){cell+='"';i++;continue}if(c==='"'){q=!q;continue}if(!q&&(c===';'||c===',')){row.push(cell);cell='';continue}if(!q&&(c==='\n'||c==='\r')){if(c==='\r'&&n==='\n')i++;row.push(cell);cell='';if(row.some(x=>x.trim()))rows.push(row);row=[];continue}cell+=c}row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows}
async function importProductsExcel(e){const f=e.target.files?.[0];if(!f)return;try{const fd=new FormData();fd.append('shopId',shopId);fd.append('file',f);toast('Читаю Excel-файл…');const r=await fetch('/api/products/import-excel',{method:'POST',headers:authToken?{authorization:`Bearer ${authToken}`}:{},body:fd});const result=await r.json().catch(()=>({}));if(!r.ok)throw new Error(result.error||'Ошибка импорта Excel');products=await api(`/api/products?shopId=${shopId}`);renderProducts();renderCategories();toast(`Excel: создано ${result.created}, обновлено ${result.updated}, ошибок ${result.errors.length}`)}catch(err){toast(err.message)}finally{e.target.value=''}}
async function importProductsCsv(e){const f=e.target.files?.[0];if(!f)return;try{const matrix=parseCsv(await f.text());if(matrix.length<2)throw new Error('CSV пуст');const heads=matrix[0].map(x=>x.trim().replace(/^\ufeff/,''));const rows=matrix.slice(1).map(r=>Object.fromEntries(heads.map((h,i)=>[h,r[i]??''])));const result=await api('/api/products/import',{method:'POST',body:JSON.stringify({shopId,rows})});products=await api(`/api/products?shopId=${shopId}`);renderProducts();renderCategories();toast(`Импорт: создано ${result.created}, обновлено ${result.updated}, ошибок ${result.errors.length}`)}catch(err){toast(err.message)}finally{e.target.value=''}}


/* v2.5 TELEGRAM STUDIO */
function openTelegramBotModal(){openModal('telegramBotModal');$('newBotName').value='';$('botToken').value=''}
function activeTelegramBot(){return telegramBots.find(x=>x.id===activeTelegramBotId)||telegramBots[0]||null}
async function loadTelegramStudio(){
  telegramBots=await api(`/api/telegram/bots?shopId=${shopId}`);
  if(!telegramBots.some(x=>x.id===activeTelegramBotId))activeTelegramBotId=telegramBots[0]?.id||null;
  telegramLogs=await api(`/api/telegram/logs?shopId=${shopId}${activeTelegramBotId?`&botId=${activeTelegramBotId}`:''}`);
  renderTelegramStudio();
}
function renderTelegramStudio(){
  const bot=activeTelegramBot();
  $('tgState').textContent=`${telegramBots.length} ${telegramBots.length===1?'бот':'ботов'}`;
  $('tgState').className='status '+(telegramBots.length?'ok':'');
  $('telegramBotList').innerHTML=telegramBots.map(b=>`<button class="bot-card ${b.id===activeTelegramBotId?'active':''}" onclick="selectTelegramBot('${b.id}')"><i class="bot-dot ${b.active?'online':''}"></i><div><b>${esc(b.name||b.username||'Telegram bot')}</b><small>@${esc(b.username||'без username')}</small></div></button>`).join('')||'<div class="empty">Подключи первого бота</div>';
  const disabled=!bot;
  document.querySelectorAll('#telegram .studio-main input,#telegram .studio-main textarea,#telegram .studio-main button').forEach(el=>{if(!['newTelegramBot'].includes(el.id))el.disabled=disabled});
  if(!bot){$('activeBotName').textContent='Telegram Studio';$('activeBotHandle').textContent='БОТ НЕ ВЫБРАН';$('botStatus').textContent='Offline';$('commandRows').innerHTML='';$('menuRows').innerHTML='';$('telegramLogRows').innerHTML='<div class="empty">Нет событий</div>';return}
  $('activeBotName').textContent=bot.name||'Telegram bot';$('activeBotHandle').textContent='@'+(bot.username||'unknown');$('botStatus').textContent=bot.active?'Подключён':'Выключен';$('botStatus').className='status '+(bot.active?'ok':'');
  $('tgBotName').value=bot.name||'';$('tgWelcome').value=bot.welcome||'';$('tgButton').value=bot.buttonText||'Открыть магазин';$('tgOrders').checked=true;$('tgStatuses').checked=true;$('tgWebhookUrl').value=bot.webhookUrl||'';$('webhookStatus').textContent=bot.webhookUrl?'Активен':'Не настроен';$('webhookStatus').className='status '+(bot.webhookUrl?'ok':'');
  $('commandRows').innerHTML='';(bot.commands||[]).forEach(addCommandRow);if(!(bot.commands||[]).length)addCommandRow();
  $('menuRows').innerHTML='';(bot.menu||[]).forEach(addMenuRow);if(!(bot.menu||[]).length)addMenuRow();
  updateTgPreview();renderTelegramLogs();
  ['tgWelcome','tgButton'].forEach(id=>$(id).oninput=updateTgPreview)
}
window.selectTelegramBot=async id=>{activeTelegramBotId=id;telegramLogs=await api(`/api/telegram/logs?shopId=${shopId}&botId=${id}`);renderTelegramStudio()}
function addCommandRow(c={}){$('commandRows').insertAdjacentHTML('beforeend',`<div class="builder-row"><input class="cmd-name" placeholder="start" value="${esc(String(c.command||'').replace(/^\//,''))}"><input class="cmd-desc" placeholder="Описание команды" value="${esc(c.description||'')}"><button onclick="this.parentElement.remove()">×</button></div>`)}
function addMenuRow(m={}){$('menuRows').insertAdjacentHTML('beforeend',`<div class="builder-row menu"><input class="menu-text" placeholder="Каталог" value="${esc(m.text||'')}"><select class="menu-action"><option value="webapp" ${m.action==='webapp'?'selected':''}>WebApp</option><option value="callback" ${m.action==='callback'?'selected':''}>Callback</option><option value="url" ${m.action==='url'?'selected':''}>URL</option><option value="command" ${m.action==='command'?'selected':''}>Команда</option></select><input class="menu-value" placeholder="/shop/demo или cart" value="${esc(m.value||'')}"><button onclick="this.parentElement.remove()">×</button></div>`)}
function collectTelegramBuilder(){
 const commands=[...document.querySelectorAll('#commandRows .builder-row')].map(r=>({command:r.querySelector('.cmd-name').value.trim().replace(/^\//,''),description:r.querySelector('.cmd-desc').value.trim()})).filter(x=>x.command&&x.description);
 const menu=[...document.querySelectorAll('#menuRows .builder-row')].map(r=>({id:'btn-'+cryptoRandom(),text:r.querySelector('.menu-text').value.trim(),action:r.querySelector('.menu-action').value,value:r.querySelector('.menu-value').value.trim()})).filter(x=>x.text);
 return{name:$('tgBotName').value.trim(),welcome:$('tgWelcome').value,buttonText:$('tgButton').value.trim(),commands,menu};
}
function cryptoRandom(){return Math.random().toString(36).slice(2,10)}
async function connectBot(){try{const bot=await api('/api/telegram/bots',{method:'POST',body:JSON.stringify({shopId,name:$('newBotName').value.trim(),token:$('botToken').value.trim()})});telegramBots.push(bot);activeTelegramBotId=bot.id;closeModal('telegramBotModal');await loadTelegramStudio();toast(`@${bot.username} подключён`)}catch(e){toast(e.message)}}
async function disconnectBot(){const bot=activeTelegramBot();if(!bot)return;if(!confirm(`Удалить подключение @${bot.username}?`))return;await api(`/api/telegram/bots/${bot.id}`,{method:'DELETE'});telegramBots=telegramBots.filter(x=>x.id!==bot.id);activeTelegramBotId=telegramBots[0]?.id||null;await loadTelegramStudio();toast('Бот удалён')}
async function saveTelegram(){const bot=activeTelegramBot();if(!bot)return;try{const saved=await api(`/api/telegram/bots/${bot.id}`,{method:'PATCH',body:JSON.stringify(collectTelegramBuilder())});telegramBots=telegramBots.map(x=>x.id===saved.id?saved:x);renderTelegramStudio();toast('Сценарий бота сохранён')}catch(e){toast(e.message)}}
async function syncTelegramCommands(){const bot=activeTelegramBot();if(!bot)return;try{await saveTelegram();await api(`/api/telegram/bots/${bot.id}/sync-commands`,{method:'POST',body:'{}'});await refreshTelegramLogs();toast('Команды синхронизированы')}catch(e){toast(e.message)}}
async function autoTelegramWebhook(){const bot=activeTelegramBot();if(!bot)return;try{const r=await api(`/api/telegram/bots/${bot.id}/auto-webhook`,{method:'POST'});bot.webhookUrl=r.webhookUrl;$('tgWebhookUrl').value=r.webhookUrl;renderTelegramStudio();await refreshTelegramLogs();toast('Webhook настроен автоматически')}catch(e){toast(e.message)}}
async function updateTelegramWebhook(remove){const bot=activeTelegramBot();if(!bot)return;try{const url=remove?'':$('tgWebhookUrl').value.trim();const r=await api(`/api/telegram/bots/${bot.id}/webhook`,{method:'POST',body:JSON.stringify({url,dropPending:$('dropPending').checked})});bot.webhookUrl=r.webhookUrl;$('tgWebhookUrl').value=r.webhookUrl;renderTelegramStudio();await refreshTelegramLogs();toast(remove?'Webhook удалён':'Webhook установлен')}catch(e){toast(e.message)}}
async function runTelegramDiagnostics(){const bot=activeTelegramBot();if(!bot)return;try{const d=await api(`/api/telegram/bots/${bot.id}/diagnostics`);$('diagnosticCards').innerHTML=`<div class="diag-card"><small>BOT API</small><b>OK</b></div><div class="diag-card"><small>LATENCY</small><b>${d.latency} ms</b></div><div class="diag-card"><small>PENDING</small><b>${d.webhook.pending_update_count||0}</b></div><div class="diag-card"><small>WEBHOOK</small><b>${d.webhook.url?'Active':'Off'}</b></div><div class="diag-card"><small>LAST ERROR</small><b>${esc(d.webhook.last_error_message||'Нет')}</b></div><div class="diag-card"><small>BOT ID</small><b>${d.bot.id}</b></div>`;await refreshTelegramLogs();toast('Диагностика завершена')}catch(e){toast(e.message)}}
async function sendTest(){const bot=activeTelegramBot();if(!bot)return;try{const shop=shops.find(x=>x.id===shopId);await api(`/api/telegram/bots/${bot.id}/test`,{method:'POST',body:JSON.stringify({chatId:$('testChat').value.trim(),text:$('testText').value,withButton:$('testWithButton').checked,webAppUrl:`${location.origin}/shop/${shop?.slug||'demo'}`})});await refreshTelegramLogs();toast('Тест отправлен')}catch(e){toast(e.message)}}
async function refreshTelegramLogs(){const bot=activeTelegramBot();telegramLogs=await api(`/api/telegram/logs?shopId=${shopId}${bot?`&botId=${bot.id}`:''}`);renderTelegramLogs()}
function renderTelegramLogs(){$('telegramLogRows').innerHTML=telegramLogs.map(l=>`<div class="tg-log-row"><small>${new Date(l.createdAt).toLocaleString('ru-RU')}</small><span class="status ${l.status==='success'?'ok':''}">${l.status}</span><b>${esc(l.type)}</b><small>${esc(l.details?.error||l.details?.username||l.details?.url||'')}</small></div>`).join('')||'<div class="empty">Событий Telegram пока нет</div>'}
function fillTelegram(){renderTelegramStudio()}

async function loadMarketing(){if(!can('orders.manage'))return;[promos,campaigns]=await Promise.all([api(`/api/promos?shopId=${shopId}`),api(`/api/campaigns?shopId=${shopId}`)]);renderMarketing()}
function renderMarketing(){if(!$('promoRows'))return;const active=promos.filter(x=>x.active).length,uses=promos.reduce((a,x)=>a+(x.used||0),0);$('marketingMetrics').innerHTML=`<div class="metric"><small>ПРОМОКОДОВ</small><strong>${promos.length}</strong></div><div class="metric"><small>АКТИВНЫХ</small><strong>${active}</strong></div><div class="metric"><small>ИСПОЛЬЗОВАНИЙ</small><strong>${uses}</strong></div><div class="metric"><small>КАМПАНИЙ</small><strong>${campaigns.length}</strong></div>`;$('promoRows').innerHTML=promos.map(p=>`<tr><td><b>${esc(p.code)}</b></td><td>${p.type==='percent'?p.value+'%':rub(p.value)}</td><td>${rub(p.minTotal)}</td><td>${p.used||0}${p.limit?' / '+p.limit:''}</td><td>${p.expiresAt?new Date(p.expiresAt).toLocaleDateString('ru-RU'):'Без срока'}</td><td><span class="status ${p.active?'ok':''}">${p.active?'Активен':'Выключен'}</span></td><td><button class="text-btn" onclick="togglePromo('${p.id}',${!p.active})">${p.active?'Выключить':'Включить'}</button> <button class="text-btn danger-link" onclick="deletePromo('${p.id}')">Удалить</button></td></tr>`).join('')||'<tr><td colspan="7"><div class="empty">Промокодов пока нет</div></td></tr>';$('campaignRows').innerHTML=campaigns.map(c=>`<div class="campaign-card"><div><b>${esc(c.name)}</b><small>${esc(c.segment)} · ${new Date(c.createdAt).toLocaleString('ru-RU')}</small><p>${esc(c.message)}</p></div><span class="status ${c.status==='sent'?'ok':''}">${c.status==='sent'?'Отправлена':'Черновик'}</span><button class="btn" onclick="sendCampaign('${c.id}')" ${c.status==='sent'?'disabled':''}>${c.status==='sent'?'Отправлено':'Запустить'}</button></div>`).join('')||'<div class="empty">Кампаний пока нет</div>'}
async function savePromo(){try{const payload={shopId,code:$('promoCode').value.trim(),type:$('promoType').value,value:Number($('promoValue').value),minTotal:Number($('promoMin').value||0),limit:Number($('promoLimit').value||0),expiresAt:$('promoExpires').value||null};await api('/api/promos',{method:'POST',body:JSON.stringify(payload)});closeModal('promoModal');await loadMarketing();toast('Промокод создан')}catch(e){toast(e.message)}}
window.togglePromo=async(id,active)=>{await api(`/api/promos/${id}`,{method:'PATCH',body:JSON.stringify({active})});await loadMarketing()};window.deletePromo=async id=>{if(!confirm('Удалить промокод?'))return;await api(`/api/promos/${id}`,{method:'DELETE'});await loadMarketing()};
async function saveCampaign(){try{await api('/api/campaigns',{method:'POST',body:JSON.stringify({shopId,name:$('campaignName').value.trim(),segment:$('campaignSegment').value,message:$('campaignMessage').value.trim()})});closeModal('campaignModal');await loadMarketing();toast('Кампания создана')}catch(e){toast(e.message)}}window.sendCampaign=async id=>{await api(`/api/campaigns/${id}/send`,{method:'POST'});await loadMarketing();toast('Рассылка отмечена как отправленная')}

/* v3.1 PLATFORM CORE */
let platformConfig=null,referrals=[],knowledgeBase=[],supportTickets=[];
const originalLoadAll=loadAll;
loadAll=async function(){await originalLoadAll();await loadPlatformCore()};
async function loadPlatformCore(){
 try{platformConfig=await api(`/api/platform-config?shopId=${shopId}`);[knowledgeBase,supportTickets]=await Promise.all([api('/api/knowledge-base'),api('/api/support/tickets')]);if(can('orders.view'))referrals=await api(`/api/referrals?shopId=${shopId}`);renderPlatformCore()}catch(e){console.warn('platform core',e)}
}
function renderPlatformCore(){renderStorefrontBuilder();renderReferrals();renderHelp();renderExtendedSettings()}
function renderStorefrontBuilder(){if(!$('sfTitle')||!platformConfig)return;const sf=platformConfig.storefront||{};$('sfTitle').value=sf.heroTitle||platformConfig.name||'';$('sfSubtitle').value=sf.heroSubtitle||platformConfig.description||'';$('sfLayout').value=sf.layout||'tiles';$('sfTheme').value=sf.theme||'ultima';$('bannerRows').innerHTML='';(sf.banners||[]).forEach(addBannerRow);$('tileRows').innerHTML='';(sf.tiles||[]).forEach(addTileRow);updateStorefrontPreview()}
function addBannerRow(b={}){$('bannerRows')?.insertAdjacentHTML('beforeend',`<div class="builder-row storefront-row"><input class="banner-title" placeholder="Название баннера" value="${esc(b.title||'')}"><input class="banner-image" placeholder="Ссылка на изображение 1200×500" value="${esc(b.image||'')}"><input class="banner-link" placeholder="Категория или URL" value="${esc(b.link||'')}"><button onclick="this.parentElement.remove();updateStorefrontPreview()">×</button></div>`);bindPreviewInputs()}
function addTileRow(t={}){$('tileRows')?.insertAdjacentHTML('beforeend',`<div class="builder-row storefront-row"><input class="tile-title" placeholder="Название раздела" value="${esc(t.title||'')}"><input class="tile-image" placeholder="Ссылка на квадратное изображение" value="${esc(t.image||'')}"><select class="tile-category"><option value="">Без категории</option>${categories.map(c=>`<option value="${c.id}" ${t.categoryId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><button onclick="this.parentElement.remove();updateStorefrontPreview()">×</button></div>`);bindPreviewInputs()}
function bindPreviewInputs(){document.querySelectorAll('#storebuilder input,#storebuilder select').forEach(x=>x.oninput=updateStorefrontPreview)}
function collectStorefront(){return{heroTitle:$('sfTitle').value.trim(),heroSubtitle:$('sfSubtitle').value.trim(),layout:$('sfLayout').value,theme:$('sfTheme').value,banners:[...document.querySelectorAll('#bannerRows .storefront-row')].map(r=>({title:r.querySelector('.banner-title').value.trim(),image:r.querySelector('.banner-image').value.trim(),link:r.querySelector('.banner-link').value.trim()})).filter(x=>x.title||x.image),tiles:[...document.querySelectorAll('#tileRows .storefront-row')].map(r=>({title:r.querySelector('.tile-title').value.trim(),image:r.querySelector('.tile-image').value.trim(),categoryId:r.querySelector('.tile-category').value})).filter(x=>x.title)}}
function updateStorefrontPreview(){if(!$('storefrontPreview'))return;const sf=collectStorefront();$('storefrontPreview').innerHTML=`<div class="preview-phone ${esc(sf.theme)}"><div class="preview-hero"><h3>${esc(sf.heroTitle||'Название магазина')}</h3><p>${esc(sf.heroSubtitle||'Описание витрины')}</p></div><div class="preview-banners">${sf.banners.slice(0,2).map(b=>`<div style="background-image:url('${esc(b.image)}')"><b>${esc(b.title)}</b></div>`).join('')||'<div><b>Баннер карусели</b></div>'}</div><div class="preview-tiles">${sf.tiles.slice(0,6).map(t=>`<div>${t.image?`<img src="${esc(t.image)}">`:''}<b>${esc(t.title)}</b></div>`).join('')||'<div><b>Плитка раздела</b></div>'}</div></div>`}
async function saveStorefront(){try{platformConfig=await api('/api/platform-config',{method:'PATCH',body:JSON.stringify({shopId,storefront:collectStorefront()})});toast('Витрина сохранена');renderStorefrontBuilder()}catch(e){toast(e.message)}}
function renderReferrals(){if(!$('referralRows'))return;$('refCount').textContent=referrals.length;$('referralRows').innerHTML=referrals.map(r=>`<div class="invoice-row"><div><b>${esc(r.telegramId)}</b><small>${esc(r.code)} · использований ${r.uses||0}</small></div><strong>${rub(r.rewardBalance||0)}</strong></div>`).join('')||'<div class="empty">Реферальных ссылок пока нет</div>'}
async function generateReferral(){try{const r=await api('/api/referrals/generate',{method:'POST',body:JSON.stringify({shopId,telegramId:$('refTelegram').value.trim()})});$('refLink').value=r.link;await navigator.clipboard?.writeText(r.link);referrals=await api(`/api/referrals?shopId=${shopId}`);renderReferrals();toast('Ссылка создана и скопирована')}catch(e){toast(e.message)}}
function renderHelp(filter=''){if(!$('kbRows'))return;const q=String(filter||'').toLowerCase();$('kbRows').innerHTML=knowledgeBase.filter(x=>!q||`${x.title} ${x.section} ${x.content}`.toLowerCase().includes(q)).map(x=>`<details class="kb-card"><summary><small>${esc(x.section)}</small><b>${esc(x.title)}</b></summary><p>${esc(x.content)}</p></details>`).join('')||'<div class="empty">Ничего не найдено</div>';$('ticketRows').innerHTML=supportTickets.slice(0,8).map(t=>`<div class="invoice-row"><div><b>#${t.number} · ${esc(t.subject)}</b><small>${new Date(t.createdAt).toLocaleString('ru-RU')}</small></div><span class="status ${t.status==='open'?'ok':''}">${t.status}</span></div>`).join('')}
async function sendSupportTicket(){try{const t=await api('/api/support/tickets',{method:'POST',body:JSON.stringify({shopId,subject:$('ticketSubject').value.trim(),message:$('ticketMessage').value.trim(),priority:$('ticketPriority').value})});supportTickets.unshift(t);$('ticketSubject').value='';$('ticketMessage').value='';renderHelp();toast(`Обращение #${t.number} создано`)}catch(e){toast(e.message)}}
function addDeliveryZoneRow(z={}){$('deliveryRows')?.insertAdjacentHTML('beforeend',`<div class="builder-row zone-row"><input class="zone-name" placeholder="Название зоны" value="${esc(z.name||'')}"><input class="zone-area" placeholder="Районы, города или индексы" value="${esc(z.area||'')}"><input class="zone-price" type="number" placeholder="Стоимость" value="${z.price||0}"><input class="zone-min" type="number" placeholder="Бесплатно от" value="${z.freeFrom||0}"><button onclick="this.parentElement.remove()">×</button></div>`)}
function addPaymentRow(m={}){$('paymentRows')?.insertAdjacentHTML('beforeend',`<div class="builder-row pay-row"><input class="pay-name" placeholder="Название: Наличные, СБП" value="${esc(m.name||'')}"><input class="pay-hint" placeholder="Подсказка покупателю" value="${esc(m.hint||'')}"><label class="check"><input class="pay-active" type="checkbox" ${m.active!==false?'checked':''}> Активен</label><button onclick="this.parentElement.remove()">×</button></div>`)}
function renderExtendedSettings(){if(!$('deliveryRows')||!platformConfig)return;const d=platformConfig.delivery||{},p=platformConfig.payments||{},a=platformConfig.autoReply||{},c=platformConfig.channels||{},i=platformConfig.integrations||{};$('deliveryEnabled').checked=!!d.enabled;$('deliveryRows').innerHTML='';(d.zones||[]).forEach(addDeliveryZoneRow);$('paymentRows').innerHTML='';(p.methods||[]).forEach(addPaymentRow);$('autoReplyEnabled').checked=!!a.enabled;$('autoReplyText').value=a.text||'';$('autoReplyImage').value=a.image||'';$('channelTelegram').checked=c.telegram!==false;$('channelMax').checked=!!c.max;$('intMoysklad').checked=!!i.moysklad?.enabled;$('int1c').checked=!!i.oneC?.enabled;$('intBitrix').checked=!!i.bitrix24?.enabled;$('intApi').checked=i.customApi?.enabled!==false}
async function savePlatformSettings(){try{await saveShop();const delivery={enabled:$('deliveryEnabled').checked,zones:[...document.querySelectorAll('#deliveryRows .zone-row')].map(r=>({name:r.querySelector('.zone-name').value.trim(),area:r.querySelector('.zone-area').value.trim(),price:Number(r.querySelector('.zone-price').value||0),freeFrom:Number(r.querySelector('.zone-min').value||0)})).filter(x=>x.name)};const payments={methods:[...document.querySelectorAll('#paymentRows .pay-row')].map(r=>({name:r.querySelector('.pay-name').value.trim(),hint:r.querySelector('.pay-hint').value.trim(),active:r.querySelector('.pay-active').checked})).filter(x=>x.name)};const autoReply={enabled:$('autoReplyEnabled').checked,text:$('autoReplyText').value,image:$('autoReplyImage').value.trim()};const channels={telegram:$('channelTelegram').checked,max:$('channelMax').checked};const integrations={moysklad:{enabled:$('intMoysklad').checked},oneC:{enabled:$('int1c').checked},bitrix24:{enabled:$('intBitrix').checked},customApi:{enabled:$('intApi').checked}};platformConfig=await api('/api/platform-config',{method:'PATCH',body:JSON.stringify({shopId,delivery,payments,autoReply,channels,integrations})});toast('Все настройки сохранены')}catch(e){toast(e.message)}}
// Hierarchical categories
const originalOpenCategory=openCategory;
openCategory=function(c){originalOpenCategory(c);$('cParent').innerHTML='<option value="">Без родителя</option>'+categories.filter(x=>x.id!==c?.id&&!x.parentId).map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('');$('cParent').value=c?.parentId||''}
saveCategory=async function(){const payload={shopId,name:$('cName').value.trim(),parentId:$('cParent').value,sort:Number($('cSort').value||99),active:$('cActive').checked};if(!payload.name)return toast('Введите название');await api(editingCategoryId?`/api/categories/${editingCategoryId}`:'/api/categories',{method:editingCategoryId?'PATCH':'POST',body:JSON.stringify(payload)});closeModal('categoryModal');categories=await api(`/api/categories?shopId=${shopId}`);renderCategories();toast('Категория сохранена')}
renderCategories=function(){const parents=categories.filter(c=>!c.parentId).sort((a,b)=>a.sort-b.sort),children=id=>categories.filter(c=>c.parentId===id).sort((a,b)=>a.sort-b.sort);$('categoryCount').textContent=categories.length;let rows=`<button class="category-item active" data-cat="all"><span>Все товары</span><b>${products.length}</b></button>`;for(const c of parents){rows+=`<div class="category-row"><button class="category-item" data-cat="${c.id}"><span>${esc(c.name)}</span><b>${products.filter(p=>p.categoryId===c.id||children(c.id).some(x=>x.id===p.categoryId)).length}</b></button><button class="icon-btn" onclick="editCategory('${c.id}')">⋯</button></div>`;for(const sub of children(c.id))rows+=`<div class="category-row subcategory"><button class="category-item" data-cat="${sub.id}"><span>↳ ${esc(sub.name)}</span><b>${products.filter(p=>p.categoryId===sub.id).length}</b></button><button class="icon-btn" onclick="editCategory('${sub.id}')">⋯</button></div>`}$('categoryList').innerHTML=rows;document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-cat]').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderProducts(b.dataset.cat)});$('pCategory').innerHTML='<option value="">Без категории</option>'+parents.map(c=>`<optgroup label="${esc(c.name)}"><option value="${c.id}">${esc(c.name)}</option>${children(c.id).map(s=>`<option value="${s.id}">— ${esc(s.name)}</option>`).join('')}</optgroup>`).join('')}
// bind newly added controls after workspace enters
const oldBindActions=bindActions;
bindActions=function(){oldBindActions();$('saveStorefront')?.addEventListener('click',saveStorefront);$('addBanner')?.addEventListener('click',()=>addBannerRow());$('addTile')?.addEventListener('click',()=>addTileRow());$('generateReferral')?.addEventListener('click',generateReferral);$('kbSearch')?.addEventListener('input',e=>renderHelp(e.target.value));$('sendTicket')?.addEventListener('click',sendSupportTicket);$('addDeliveryZone')?.addEventListener('click',()=>addDeliveryZoneRow());$('addPaymentMethod')?.addEventListener('click',()=>addPaymentRow());$('savePlatformSettings')?.addEventListener('click',savePlatformSettings)}
